//! M2.4 — fit `TptLadder` against the vcf303 ngspice gold.
//!
//! Gold metrics live in `eval/303/vcf303_gold.json`, generated by
//! `run_vcf303_spice.py --json` (ngspice-46, the Phase-1 circuit IR — ground truth).
//! We assert the ideal TPT ladder reproduces the *bias-robust* invariants of the
//! real diode ladder within bounded error. Absolute dB levels are NOT compared:
//! the SPICE passband gain peaks with the bias current (diff-pair gm), so only
//! shape-invariant quantities (corner ratio, resonance-at-cutoff, per-pole tap
//! step) are meaningful across the circuit↔DSP gap.

use plugin303::dsp::ladder::TptLadder;
use serde_json::Value;

const SR: f32 = 48_000.0;

/// Steady-state linear gain (out_rms / in_rms) of a freshly-configured filter at
/// `freq`, driven small so the per-stage tanh stays in its linear region (AC fit).
fn gain_at(cfg: &dyn Fn(&mut TptLadder), freq: f32) -> f32 {
    let amp = 0.02;
    let mut f = TptLadder::new(SR);
    cfg(&mut f);
    let warmup = 6_000;
    let n = 12_000;
    let mut ph = 0.0f32;
    let mut acc = 0.0f32;
    for i in 0..(warmup + n) {
        let x = amp * (2.0 * std::f32::consts::PI * ph).sin();
        let y = f.tick(x);
        if i >= warmup {
            acc += y * y;
        }
        ph += freq / SR;
        if ph >= 1.0 {
            ph -= 1.0;
        }
    }
    let out_rms = (acc / n as f32).sqrt();
    let in_rms = amp / 2.0f32.sqrt();
    out_rms / in_rms
}

/// Magnitude in dB relative to the passband (measured at 50 Hz).
fn mag_db_rel(cfg: &dyn Fn(&mut TptLadder), freq: f32, passband_gain: f32) -> f32 {
    20.0 * (gain_at(cfg, freq) / passband_gain).log10()
}

fn log_sweep(lo: f32, hi: f32, n: usize) -> Vec<f32> {
    (0..n)
        .map(|i| lo * (hi / lo).powf(i as f32 / (n - 1) as f32))
        .collect()
}

fn gold() -> Value {
    let raw = include_str!("../../eval/303/vcf303_gold.json");
    serde_json::from_str(raw).expect("gold fixture parses")
}

#[test]
fn corner_ratio_matches_gold() {
    let g = gold();
    let f_peak = g["reso"]["f_peak_hz"].as_f64().unwrap() as f32; // ~ the corner
    let f_deep = g["cutoff"]["f_deep_hz"].as_f64().unwrap() as f32;
    let gold_ratio = f_deep / f_peak; // shape-invariant: -60dB point / corner

    // Plugin: set cutoff at the gold corner, measure its own -60 dB crossing.
    let cfg = |f: &mut TptLadder| {
        f.set_cutoff(f_peak);
        f.set_reso(0.0);
        f.set_poles(4);
    };
    let pb = gain_at(&cfg, 50.0);
    let freqs = log_sweep(f_peak, f_peak * 12.0, 80);
    let mut f_deep_plugin = f32::NAN;
    let mut prev = (freqs[0], mag_db_rel(&cfg, freqs[0], pb));
    for &fr in &freqs[1..] {
        let m = mag_db_rel(&cfg, fr, pb);
        if m <= -60.0 && prev.1 > -60.0 {
            // log-linear interpolate the crossing
            let t = (-60.0 - prev.1) / (m - prev.1);
            f_deep_plugin = (prev.0.ln() + t * (fr.ln() - prev.0.ln())).exp();
            break;
        }
        prev = (fr, m);
    }
    assert!(f_deep_plugin.is_finite(), "plugin never reached -60 dB");
    let plugin_ratio = f_deep_plugin / f_peak;
    let rel = plugin_ratio / gold_ratio;
    assert!(
        (0.8..1.25).contains(&rel),
        "corner ratio off: plugin={plugin_ratio:.2} gold={gold_ratio:.2} (rel {rel:.2})"
    );
}

#[test]
fn resonance_peaks_at_cutoff_and_reaches_gold_height() {
    let g = gold();
    let f_peak = g["reso"]["f_peak_hz"].as_f64().unwrap() as f32;
    let gold_peak_db = g["reso"]["max_peak_db"].as_f64().unwrap() as f32;

    // Reso tuned so the ideal TPT peak height matches the gold ~20 dB; this lets
    // the height check below be two-sided (k chosen empirically: 0.85 -> ~20.5 dB).
    let cfg = |f: &mut TptLadder| {
        f.set_cutoff(f_peak);
        f.set_reso(0.85);
        f.set_poles(4);
    };
    let pb = gain_at(&cfg, 50.0);
    let freqs = log_sweep(f_peak * 0.3, f_peak * 3.0, 120);
    let (mut best_db, mut best_f) = (f32::NEG_INFINITY, f32::NAN);
    for &fr in &freqs {
        let m = mag_db_rel(&cfg, fr, pb);
        if m > best_db {
            best_db = m;
            best_f = fr;
        }
    }
    // Peak sits at the cutoff (within 30%). NB: the TPT ladder peaks at its
    // configured cutoff by construction, so this gates `set_cutoff` calibration
    // more than gold fidelity — the height check below carries the fidelity claim.
    let f_rel = best_f / f_peak;
    assert!(
        (0.7..1.3).contains(&f_rel),
        "resonance peak at {best_f:.0} Hz, cutoff {f_peak:.0} Hz (rel {f_rel:.2})"
    );
    // Two-sided: the plugin must match the real circuit's resonant height, not
    // merely exceed it — a runaway / self-oscillating peak fails here too.
    assert!(
        (best_db - gold_peak_db).abs() < 3.0,
        "resonance peak {best_db:.1} dB vs gold {gold_peak_db:.1} dB"
    );
}

#[test]
fn tap_select_per_pole_step_matches_gold() {
    let g = gold();
    let f_peak = g["reso"]["f_peak_hz"].as_f64().unwrap() as f32;
    let f_ref = g["f_ref_hz"].as_f64().unwrap() as f32;
    let a = &g["taps_atten_db"];
    let gold_p4 = a["p4_tl"].as_f64().unwrap() as f32;
    let gold_p3 = a["p3_bl"].as_f64().unwrap() as f32;
    let gold_p2 = a["p2_cl"].as_f64().unwrap() as f32;
    let gold_step_43 = gold_p3 - gold_p4; // ~ +13.7 dB (less attenuation per pole down)
    let gold_step_32 = gold_p2 - gold_p3; // ~ +14.5 dB

    let atten = |poles: usize| -> f32 {
        let cfg = move |f: &mut TptLadder| {
            f.set_cutoff(f_peak);
            f.set_reso(0.0);
            f.set_poles(poles);
        };
        let pb = gain_at(&cfg, 50.0);
        mag_db_rel(&cfg, f_ref, pb)
    };
    let (p4, p3, p2) = (atten(4), atten(3), atten(2));
    // Monotone: fewer poles -> less attenuation.
    assert!(
        p4 < p3 && p3 < p2,
        "taps not monotone: p4={p4:.1} p3={p3:.1} p2={p2:.1}"
    );

    let step_43 = p3 - p4;
    let step_32 = p2 - p3;

    // The per-pole step of any identical-1-pole cascade is `20*log10(f_ref/fc)` per
    // tap — the diode ladder shares this, and the gold steps (~13.7/14.5 dB) sit on
    // it. So this also gates `set_cutoff` calibration: a mistuned effective cutoff
    // shifts `f_ref/fc` and the step with it. Probe at the gold corner ratio
    // (cutoff = f_peak, measured at f_ref) and hold both the analytic value and the
    // gold to a tight 2.5 dB — that caps the tolerated cutoff error at
    // 10^(2.5/20) ~ 1.33x (~0.4 octave) instead of the old 5 dB / ~0.83 octave.
    let analytic_step = 20.0 * (f_ref / f_peak).log10();
    for (label, step) in [("4->3", step_43), ("3->2", step_32)] {
        assert!(
            (step - analytic_step).abs() < 2.5,
            "{label} step {step:.1} dB off analytic identical-cascade {analytic_step:.1} dB"
        );
    }
    assert!(
        (step_43 - gold_step_43).abs() < 2.5,
        "4->3 step {step_43:.1} dB vs gold {gold_step_43:.1} dB"
    );
    assert!(
        (step_32 - gold_step_32).abs() < 2.5,
        "3->2 step {step_32:.1} dB vs gold {gold_step_32:.1} dB"
    );
}
